//
//  SortingAlgorithms.swift
//  常见排序算法实现：冒泡、插入、选择、希尔、归并、快排、堆排
//

import Foundation

// MARK: - 排序算法协议
protocol Sortable {
    func bubbleSort(_ arr: inout [Int])
    func insertionSort(_ arr: inout [Int])
    func selectionSort(_ arr: inout [Int])
    func shellSort(_ arr: inout [Int])
    func mergeSort(_ arr: inout [Int])
    func quickSort(_ arr: inout [Int])
    func heapSort(_ arr: inout [Int])
}

// MARK: - 排序算法实现
struct SortingAlgorithms: Sortable {

    /// 冒泡排序（O(n²)，稳定）
    func bubbleSort(_ arr: inout [Int]) {
        let n = arr.count
        for i in 0..<max(n - 1, 0) {
            var swapped = false
            for j in 0..<(n - i - 1) {
                if arr[j] > arr[j + 1] {
                    arr.swapAt(j, j + 1)
                    swapped = true
                }
            }
            if !swapped { break } // 提前结束
        }
    }

    /// 插入排序（O(n²)，稳定，适合近乎有序数组）
    func insertionSort(_ arr: inout [Int]) {
        for i in 1..<arr.count {
            let key = arr[i]
            var j = i - 1
            while j >= 0 && arr[j] > key {
                arr[j + 1] = arr[j]
                j -= 1
            }
            arr[j + 1] = key
        }
    }

    /// 选择排序（O(n²)，不稳定）
    func selectionSort(_ arr: inout [Int]) {
        let n = arr.count
        for i in 0..<max(n - 1, 0) {
            var minIdx = i
            for j in (i + 1)..<n where arr[j] < arr[minIdx] {
                minIdx = j
            }
            if minIdx != i {
                arr.swapAt(i, minIdx)
            }
        }
    }

    /// 希尔排序（O(n log n) ~ O(n^1.5)，不稳定）
    func shellSort(_ arr: inout [Int]) {
        let n = arr.count
        var gap = n / 2
        while gap > 0 {
            for i in gap..<n {
                let temp = arr[i]
                var j = i
                while j >= gap && arr[j - gap] > temp {
                    arr[j] = arr[j - gap]
                    j -= gap
                }
                arr[j] = temp
            }
            gap /= 2
        }
    }

    /// 归并排序（O(n log n)，稳定）
    func mergeSort(_ arr: inout [Int]) {
        guard arr.count > 1 else { return }
        mergeSortRecursive(&arr, 0, arr.count - 1, buffer: &buffer)
    }

    private var buffer: [Int] = []

    private func mergeSortRecursive(_ arr: inout [Int], _ l: Int, _ r: Int, buffer: inout [Int]) {
        guard l < r else { return }
        let mid = l + (r - l) / 2
        mergeSortRecursive(&arr, l, mid, buffer: &buffer)
        mergeSortRecursive(&arr, mid + 1, r, buffer: &buffer)
        merge(&arr, l, mid, r, buffer: &buffer)
    }

    private func merge(_ arr: inout [Int], _ l: Int, _ mid: Int, _ r: Int, buffer: inout [Int]) {
        let leftSlice = arr[l...mid]
        let rightSlice = arr[mid + 1...r]
        var i = 0
        var j = 0
        var k = l

        while i < leftSlice.count && j < rightSlice.count {
            if leftSlice[i] <= rightSlice[j] {
                buffer[k] = leftSlice[i]
                i += 1
            } else {
                buffer[k] = rightSlice[j]
                j += 1
            }
            k += 1
        }

        while i < leftSlice.count {
            buffer[k] = leftSlice[i]
            i += 1
            k += 1
        }
        while j < rightSlice.count {
            buffer[k] = rightSlice[j]
            j += 1
            k += 1
        }

        arr[l...r] = buffer[l...r]
    }

    /// 快速排序（平均 O(n log n)，不稳定）
    func quickSort(_ arr: inout [Int]) {
        quickSort(&arr, 0, arr.count - 1)
    }

    private func quickSort(_ arr: inout [Int], _ low: Int, _ high: Int) {
        guard low < high else { return }
        let pivotIdx = partition(&arr, low, high)
        quickSort(&arr, low, pivotIdx - 1)
        quickSort(&arr, pivotIdx + 1, high)
    }

    private func partition(_ arr: inout [Int], _ low: Int, _ high: Int) -> Int {
        let pivot = arr[high]
        var i = low - 1
        for j in low..<high {
            if arr[j] <= pivot {
                i += 1
                arr.swapAt(i, j)
            }
        }
        arr.swapAt(i + 1, high)
        return i + 1
    }

    /// 堆排序（O(n log n)，不稳定）
    func heapSort(_ arr: inout [Int]) {
        let n = arr.count
        // 建最大堆
        for i in (n / 2 - 1)..<0 {
            heapify(&arr, i, heapSize: n)
        }
        // 逐步提取堆顶
        for end in stride(from: n - 1, to: 0, by: -1) {
            arr.swapAt(0, end)
            heapify(&arr, 0, heapSize: end)
        }
    }

    private func heapify(_ arr: inout [Int], _ i: Int, heapSize: Int) {
        var largest = i
        let left = 2 * i + 1
        let right = 2 * i + 2

        if left < heapSize && arr[left] > arr[largest] {
            largest = left
        }
        if right < heapSize && arr[right] > arr[largest] {
            largest = right
        }
        if largest != i {
            arr.swapAt(i, largest)
            heapify(&arr, largest, heapSize: heapSize)
        }
    }
}

// MARK: - 演示
extension SortingAlgorithms {
    /// 对同一组数据跑全部算法并打印结果
    static func runDemo() {
        let data = [5, 3, 8, 1, 9, 2, 7, 4, 6, 0]
        print("原始数据:", data)

        var s = SortingAlgorithms()

        var arr1 = data; s.bubbleSort(&arr1);    print("冒泡排序:", arr1)
        var arr2 = data; s.insertionSort(&arr2);  print("插入排序:", arr2)
        var arr3 = data; s.selectionSort(&arr3);  print("选择排序:", arr3)
        var arr4 = data; s.shellSort(&arr4);      print("希尔排序:", arr4)
        var arr5 = data; s.mergeSort(&arr5);      print("归并排序:", arr5)
        var arr6 = data; s.quickSort(&arr6);      print("快速排序:", arr6)
        var arr7 = data; s.heapSort(&arr7);       print("堆排序:  ", arr7)
    }
}

// 直接以 swift SortingAlgorithms.swift 方式运行时执行演示
#if !canImport(Darwin) || true
SortingAlgorithms.runDemo()
#endif
